// The default temporary folder location for use in the windows algorithm.
// It's TEMPting to use dirname(path), since that's guaranteed to be on the
// same device.  However, this means that:
// rimraf(path).then(() => rimraf(dirname(path)))
// will often fail with EBUSY, because the parent dir contains
// marked-for-deletion directory entries (which do not show up in readdir).
// The approach here is to use os.tmpdir() if it's on the same drive letter,
// or resolve(path, '\\temp') if it exists, or the root of the drive if not.
// On Posix (not that you'd be likely to use the windows algorithm there),
// it uses os.tmpdir() always.
import { tmpdir } from 'os'
import { parse, resolve } from 'path'
import { promises, statSync } from './fs.js'
const { stat } = promises

const isDirSync = (path: string) => {
  try {
    return statSync(path).isDirectory()
  } catch {
    return false
  }
}

const isDir = (path: string) =>
  stat(path).then(
    st => st.isDirectory(),
    () => false,
  )

const win32DefaultTmp = async (path: string) => {
  const { root } = parse(path)
  const tmp = tmpdir()
  const { root: tmpRoot } = parse(tmp)
  if (root.toLowerCase() === tmpRoot.toLowerCase()) {
    return tmp
  }

  const driveTmp = resolve(root, '/temp')
  if (await isDir(driveTmp)) {
    return driveTmp
  }

  return root
}

const win32DefaultTmpSync = (path: string) => {
  const { root } = parse(path)
  const tmp = tmpdir()
  const { root: tmpRoot } = parse(tmp)
  if (root.toLowerCase() === tmpRoot.toLowerCase()) {
    return tmp
  }

  const driveTmp = resolve(root, '/temp')
  if (isDirSync(driveTmp)) {
    return driveTmp
  }

  return root
}

// eslint-disable-next-line @typescript-eslint/require-await
const posixDefaultTmp = async () => tmpdir()
const posixDefaultTmpSync = () => tmpdir()

export const defaultTmp =
  process.platform === 'win32' ? win32DefaultTmp : posixDefaultTmp
export const defaultTmpSync =
  process.platform === 'win32' ? win32DefaultTmpSync : posixDefaultTmpSync

const isRecord = (o: unknown): o is Record<string, unknown> =>
  !!o && typeof o === 'object'

const hasString = (o: Record<string, unknown>, key: string) =>
  key in o && typeof o[key] === 'string'

export const isFsError = (
  o: unknown,
): o is NodeJS.ErrnoException & {
  code: string
  path: string
} => isRecord(o) && hasString(o, 'code') && hasString(o, 'path')

export const errorCode = (er: unknown) =>
  isRecord(er) && hasString(er, 'code') ? er.code : null

import { errorCode } from './error.js'
import { chmodSync, promises } from './fs.js'
import { ignoreENOENT, ignoreENOENTSync } from './ignore-enoent.js'
const { chmod } = promises

export const fixEPERM =
  (fn: (path: string) => Promise<unknown>) =>
  async (path: string): Promise<void> => {
    try {
      return void (await ignoreENOENT(fn(path)))
    } catch (er) {
      if (errorCode(er) === 'EPERM') {
        if (
          !(await ignoreENOENT(
            chmod(path, 0o666).then(() => true),
            er,
          ))
        ) {
          return
        }
        return void (await fn(path))
      }
      throw er
    }
  }

export const fixEPERMSync =
  (fn: (path: string) => unknown) =>
  (path: string): void => {
    try {
      return void ignoreENOENTSync(() => fn(path))
    } catch (er) {
      if (errorCode(er) === 'EPERM') {
        if (!ignoreENOENTSync(() => (chmodSync(path, 0o666), true), er)) {
          return
        }
        return void fn(path)
      }
      throw er
    }
  }

import { errorCode } from './error.js'

export const ignoreENOENT = async <T>(p: Promise<T>, rethrow?: unknown) =>
  p.catch(er => {
    if (errorCode(er) === 'ENOENT') {
      return
    }
    throw rethrow ?? er
  })

export const ignoreENOENTSync = <T>(fn: () => T, rethrow?: unknown) => {
  try {
    return fn()
  } catch (er) {
    if (errorCode(er) === 'ENOENT') {
      return
    }
    throw rethrow ?? er
  }
}

// returns an array of entries if readdir() works,
// or the error that readdir() raised if not.
import { promises, readdirSync } from './fs.js'
const { readdir } = promises

export const readdirOrError = (path: string) =>
  readdir(path).catch(er => er as Error)
export const readdirOrErrorSync = (path: string) => {
  try {
    return readdirSync(path)
  } catch (er) {
    return er as Error
  }
}

